def transform(grid):
    R, C = len(grid), len(grid[0])
    flat = Counter(v for row in grid for v in row)
    bg = flat.most_common(1)[0][0]
    g = [row[:] for row in grid]

    top_cols = [c for c in range(C) if grid[0][c] != bg]
    bot_cols = [c for c in range(C) if grid[R-1][c] != bg]
    block_colors = set(grid[0][c] for c in top_cols) | set(grid[R-1][c] for c in bot_cols)

    def is_block(v):
        return v != bg and v in block_colors

    pixels = []
    for r in range(1, R-1):
        for c in range(C):
            if grid[r][c] != bg and not is_block(grid[r][c]):
                pixels.append((r, c))
