    if top_cols and bot_cols:
        b = min(bot_cols, key=lambda c: min(abs(c - t) for t in top_cols))
        for r in range(R):
            if is_block(grid[r][b]):
                continue
            g[r][b] = line_color

    # pixel columns: fill from top down to lowest pixel, skipping block cells
    lowest = {}
    for (r, c) in pixels:
        lowest[c] = max(lowest.get(c, -1), r)
