Now I can reconcile all four demos. The rule: two anchor-colored blocks (top/bottom, or left/right), plus stray pixels of a "line" color. Each pixel gets: (a) a full line of its color perpendicular-aligned at an offset position — offset = (bottom block's right edge − top block's right edge) applied to the pixel's column (demo1: 7+(2−7)=2 ✓; demo2: 2+(1−3)=0 ✓; demo4: 8+(4−9)=3 ✓; demo3 transposed: rows 6+5=11, 7+5=12 ✓); and (b) a line in the pixel's own row/column from just past the first anchor to the pixel, skipping anchor-colored cells; pixels become 4.

```python
from collections import Counter

def transform(grid):
    R, C = len(grid), len(grid[0])
    cnt = Counter(v for row in grid for v in row)
    bg = cnt.most_common(1)[0][0]
    g = [row[:] for row in grid]

    top_anchor = [grid[0][c] for c in range(C) if grid[0][c] != bg]
    bot_anchor = [grid[R-1][c] for c in range(C) if grid[R-1][c] != bg]

    if top_anchor and bot_anchor:
        # vertical-line mode: top block in row 0, bottom block in last row
        anchor_colors = set(top_anchor) | set(bot_anchor)
        top_cols = [c for c in range(C) if grid[0][c] != bg]
        bot_cols = [c for c in range(C) if grid[R-1][c] != bg]
        delta = max(bot_cols) - max(top_cols)
        pixels = [(r, c) for r in range(1, R-1) for c in range(C)
                  if grid[r][c] != bg and grid[r][c] not in anchor_colors]
        if not pixels:
            return g
        line = grid[pixels[0][0]][pixels[0][1]]
        for (r, c) in pixels:
            fc = c + delta
            if 0 <= fc < C:
                for rr in range(R):
                    if grid[rr][fc] not in anchor_colors:
                        g[rr][fc] = line
            for rr in range(1, r + 1):
                if grid[rr][c] not in anchor_colors:
                    g[rr][c] = line
        for (r, c) in pixels:
            g[r][c] = 4
        return g

    # horizontal-line mode (like demo 3)
    anchor_count = Counter(v for row in grid for v in row if v != bg)
    if not anchor_count:
        return g
    anchor = max(anchor_count, key=anchor_count.get)
    pixels = [(r, c) for r in range(R) for c in range(C)
              if grid[r][c] != bg and grid[r][c] != anchor]
    if not pixels:
        return g
    line = grid[pixels[0][0]][pixels[0][1]]
    anchor_cols = [c for c in range(C) if any(grid[r][c] == anchor for r in range(R))]
    if not anchor_cols:
        return g
    lc, rc = min(anchor_cols), max(anchor_cols)
    l_bottom = max(r for r in range(R) if grid[r][lc] == anchor)
    r_bottom = max(r for r in range(R) if grid[r][rc] == anchor)
    delta = r_bottom - l_bottom
    for (r, c) in pixels:
        fr = r + delta
        if 0 <= fr < R:
            for cc in range(C):
                if grid[fr][cc] != anchor:
                    g[fr][cc] = line
        for cc in range(lc + 1, c + 1):
            if grid[r][cc] != anchor:
                g[r][cc] = line
    for (r, c) in pixels:
        g[r][c] = 4
    return g
